245:     private static void AssertExpectedAliasRaceRejection(Exception failure)
246:     {
247:         var message = failure.Message;
248:         Assert.False(string.IsNullOrWhiteSpace(message));
249: 
250:         if (failure is UnauthorizedAccessException unauthorized)
251:         {
252:             var nativeCode = unauthorized.HResult & 0xFFFF;
253:             Assert.Contains(nativeCode, new[] { 5, 13 });
254:             return;
255:         }
256: 
257:         var ioFailure = Assert.IsAssignableFrom<IOException>(failure);
258:         var expectedContractMessage = new[]
259:         {
260:             "Unable to pin contained directory",
261:             "Unable to pin contained directory segment",
262:             "Unable to open contained file",
263:             "Contained directory is not an ordinary",
264:             "Contained entry is not an ordinary",
265:             "Contained file changed while it was opened",
266:             "Opened entry escaped the workspace root",
267:         }.Any(prefix =>
268:             message.StartsWith(prefix, StringComparison.Ordinal));
269:         var nativeError = ioFailure.InnerException is System.ComponentModel.Win32Exception win32
270:             ? win32.NativeErrorCode
271:             : ioFailure.HResult & 0xFFFF;
272:         var expectedNativeError = OperatingSystem.IsWindows()
273:             ? new[] { 2, 3, 5, 32, 33, 4390, 4392, 4393 }.Contains(nativeError)
274:             : new[] { 2, 13, 20, 40, 116 }.Contains(nativeError);
275: 
276:         Assert.True(
277:             expectedContractMessage || expectedNativeError,
278:             $"Unexpected alias-race failure: {failure}");
