383:     private static bool IsLexicallyContained(string root, string candidate)
384:     {
385:         if (string.Equals(root, candidate, PathComparison))
386:             return true;
387:         var rootWithSeparator = Path.EndsInDirectorySeparator(root)
388:             ? root
389:             : root + Path.DirectorySeparatorChar;
390:         return candidate.StartsWith(rootWithSeparator, PathComparison);
391:     }
