607:     [SupportedOSPlatform("windows")]
608:     private static SafeFileHandle? OpenWindowsRelative(
609:         SafeFileHandle parent,
610:         string name,
611:         uint desiredAccess,
612:         uint shareAccess,
613:         uint createDisposition,
614:         uint createOptions,
615:         bool allowMissing,
616:         string errorMessage)
617:     {
618:         if (name.Length > (ushort.MaxValue / sizeof(char)) - 1)
619:             throw new IOException($"Contained path segment is too long: {name}");
620: 
621:         var nameBuffer = Marshal.StringToHGlobalUni(name);
622:         var unicodeStringPointer = Marshal.AllocHGlobal(Marshal.SizeOf<UnicodeString>());
623:         try
624:         {
625:             var unicodeString = new UnicodeString
626:             {
627:                 Length = checked((ushort)(name.Length * sizeof(char))),
628:                 MaximumLength = checked((ushort)((name.Length + 1) * sizeof(char))),
629:                 Buffer = nameBuffer,
630:             };
631:             Marshal.StructureToPtr(unicodeString, unicodeStringPointer, fDeleteOld: false);
632:             var attributes = new ObjectAttributes
633:             {
634:                 Length = Marshal.SizeOf<ObjectAttributes>(),
635:                 RootDirectory = parent.DangerousGetHandle(),
636:                 ObjectName = unicodeStringPointer,
637:                 Attributes = ObjectCaseInsensitive,
638:             };
639:             var status = NtCreateFile(
640:                 out var handle,
641:                 desiredAccess,
642:                 ref attributes,
643:                 out _,
644:                 IntPtr.Zero,
645:                 0,
646:                 shareAccess,
647:                 createDisposition,
648:                 createOptions,
649:                 IntPtr.Zero,
650:                 0);
651:             if (status >= 0 && handle is not null && !handle.IsInvalid)
652:                 return handle;
653: 
654:             handle?.Dispose();
655:             var error = unchecked((int)RtlNtStatusToDosError(status));
656:             if (allowMissing && error is 2 or 3)
657:                 return null;
658:             throw new IOException(errorMessage, new Win32Exception(error));
659:         }
660:         finally
661:         {
662:             Marshal.FreeHGlobal(unicodeStringPointer);
663:             Marshal.FreeHGlobal(nameBuffer);
664:         }
665:     }
